// UI strings generated by app.js / viz.js. The page language comes from <html lang>.
// Entries are strings or functions; functions may return arrays mixing text and DOM
// nodes (h() flattens them), so messages can embed token chips.

export const LANG = document.documentElement.lang?.startsWith("ru") ? "ru" : "en";

const enN = (n, one, many) => (n === 1 ? one : many);
const ruN = (n, one, few, many) => {
  const a = Math.abs(n) % 100;
  const b = a % 10;
  if (a > 10 && a < 20) return many;
  if (b === 1) return one;
  return b >= 2 && b <= 4 ? few : many;
};
const intEn = (n) => n.toLocaleString("en-US");
const intRu = (n) => n.toLocaleString("ru-RU");

